package com.ruoyi.web.controller.meeting;
import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.ruoyi.common.core.controller.BaseController; import com.ruoyi.common.core.domain.AjaxResult; import com.ruoyi.system.service.IYcMeetingFeedbackService;
@RestController @RequestMapping("/meeting/feedback") public class YcFeedbackController extends BaseController { @Autowired private IYcMeetingFeedbackService service; @PreAuthorize("@ss.hasPermi('meeting:dashboard:view')") @GetMapping("/stats/{activityId}") public AjaxResult stats(@PathVariable Long activityId){return success(service.stats(activityId));} @PreAuthorize("@ss.hasPermi('meeting:dashboard:view')") @GetMapping("/list/{activityId}") public AjaxResult list(@PathVariable Long activityId){return success(service.list(activityId));} }
